//! Independent outlet-control headwater on sediment-reduced sections, with weighted-perimeter
//! friction and the face entrance loss `ke / (1 - f)^2 + (f / (1 - f))^2`.
//!
//! Depths and heads run up from the bed. Each pair holds the round-down and round-up
//! binary64 bits of the reference value.

// Generated by `transcribe.py` in `resource/evidence/culvert-blockage/` from its frozen
// `outlet.json`. Regenerate instead of editing.

/// SHA256 of the frozen `outlet.json`.
pub const OUTLET_SHA256: &str = "086890977b581cfaee26ff0cfc0c1880d48b9dd961e90ca170892461c05aa036";

pub const GRAVITY: u64 = 0x40239eb851eb851f;
pub const FULL_RELATIVE_TOLERANCE: f64 = 9.094947017729282e-13;
pub const PROFILE_RELATIVE_TOLERANCE: f64 = 1e-09;
pub const FACE_LOSS_RELATIVE_TOLERANCE: f64 = 3.552713678800501e-15;
/// Jump position tolerance, relative to the barrel length.
pub const JUMP_POSITION_TOLERANCE: f64 = 1e-06;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Flow {
    Full,
    PartlyFull,
    Supercritical,
    Jump,
    CriticalFullOutlet,
}

/// One outlet section: its name in `section_rows::SECTIONS`, bed and friction inputs.
#[derive(Clone, Copy, Debug)]
pub struct OutletSection {
    pub name: &'static str,
    pub sediment_depth: u64,
    pub reduced_rise: u64,
    pub roughness_ratio: u64,
    pub wall_manning: u64,
    pub peak_depth: Option<[u64; 2]>,
}

/// Face entrance loss at one `ke` and face fraction.
#[derive(Clone, Copy, Debug)]
pub struct FaceLoss {
    pub ke: u64,
    pub face_fraction: u64,
    pub face_ke: [u64; 2],
}

/// Hydraulic jump of a steep row: its distance from the inlet and both conjugate depths.
#[derive(Clone, Copy, Debug)]
pub struct Jump {
    pub position: [u64; 2],
    pub upstream_depth: [u64; 2],
    pub downstream_depth: [u64; 2],
}

/// One outlet row. `normal_depth` is `None` on a full row or a non-positive slope.
/// `outlet_depth` is the supercritical depth at the outlet of a supercritical row.
#[derive(Clone, Copy, Debug)]
pub struct Outlet {
    pub section: usize,
    pub name: &'static str,
    pub length: u64,
    pub slope: u64,
    pub wall_manning: u64,
    pub ke: u64,
    pub face_fraction: u64,
    pub face_ke: [u64; 2],
    pub discharge: u64,
    pub tailwater: u64,
    pub flow: Flow,
    pub headwater: [u64; 2],
    pub inlet_head: Option<[u64; 2]>,
    pub critical_depth: Option<[u64; 2]>,
    pub normal_depth: Option<[u64; 2]>,
    pub outlet_depth: Option<[u64; 2]>,
    pub jump: Option<Jump>,
}

